using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using StartApp.App;
using StartApp.Core;
using StartApp.Presentation;
using StartApp.Storage.Json;
using Application=System.Windows.Application;
using Button=System.Windows.Controls.Button;
using TextBox=System.Windows.Controls.TextBox;
class Program {
[System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool IsWindowEnabled(IntPtr handle);
static IEnumerable<DependencyObject> Tree(DependencyObject x){yield return x;for(int i=0;i<VisualTreeHelper.GetChildrenCount(x);i++)foreach(var y in Tree(VisualTreeHelper.GetChild(x,i)))yield return y;}
static List<object> checks=new();static void Check(string n,bool b){checks.Add(new{name=n,ok=b});if(!b)throw new Exception(n);}
static async Task Click(Button b){var peer=new System.Windows.Automation.Peers.ButtonAutomationPeer(b);((System.Windows.Automation.Provider.IInvokeProvider)peer.GetPattern(System.Windows.Automation.Peers.PatternInterface.Invoke)).Invoke();await b.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);}
static async Task Shot(Window w,string path){w.UpdateLayout();await Task.Delay(200);var p=w.PointToScreen(new System.Windows.Point());using var image=new System.Drawing.Bitmap((int)w.ActualWidth,(int)w.ActualHeight);using(var g=System.Drawing.Graphics.FromImage(image))g.CopyFromScreen((int)p.X,(int)p.Y,0,0,image.Size);image.Save(path);}
[STAThread]static int Main(string[] args){string output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};app.Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("pack://application:,,,/StartApp.App;component/SharedResources.xaml")});using var repo=new JsonStore(Path.Combine(output,"store.json"));repo.Mutate(c=>{c.CreateWorkspace("סביבת עבודה ראשונה");c.CreateWorkspace("סביבת יעד לבדיקה");});var vm=new MainViewModel(repo,new NotImplementedLauncher());var window=new MainWindow(new UpdateViewModel(new InactiveUpdateSource(),null,_=>throw new Exception())){DataContext=vm,Width=1000,Height=720};int exit=0;
window.ContentRendered+=async(_,_)=>{try{var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=async(_,_)=>{if(!Application.Current.Windows.OfType<CardAddWindow>().Any())return;timer.Stop();try{var dialog=Application.Current.Windows.OfType<CardAddWindow>().Single();Check("owner stays on cards",vm.InOverview);Check("owner modal",dialog.Owner==window&&!IsWindowEnabled(new System.Windows.Interop.WindowInteropHelper(window).Handle));var child=(MainViewModel)dialog.DataContext;Check("correct clicked workspace",child.Selected!.Name=="סביבת יעד לבדיקה");await Shot(dialog,Path.Combine(output,"01-card-add.png"));var box=Tree(dialog).OfType<TextBox>().Single(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="Item target");box.Text="https://example.com/";await dialog.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);await Click(Tree(dialog).OfType<Button>().Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="Add item"));Check("saved only in target",repo.Load().Workspaces.Single(w=>w.Name=="סביבת יעד לבדיקה").Items.Count==1&&repo.Load().Workspaces.First().Items.Count==0);box.Text="https://example.com/";await Click(Tree(dialog).OfType<Button>().Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="Add item"));Check("duplicate blocks save",child.DuplicatePending&&repo.Load().Workspaces.Last().Items.Count==1);await Shot(dialog,Path.Combine(output,"02-duplicate.png"));child.NewTarget="https://draft.example/";dialog.Close();Check("draft close guarded",dialog.IsVisible);await Shot(dialog,Path.Combine(output,"03-close-guard.png"));await Click(Tree(dialog).OfType<Button>().Single(b=>b.Content as string=="צא בלי לשמור"));Check("discard leaves saved item unchanged",repo.Load().Workspaces.Last().Items.Count==1);}catch(Exception e){File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;foreach(var w in Application.Current.Windows.OfType<CardAddWindow>().ToArray()){((MainViewModel)w.DataContext).NewTarget="";w.Close();}}};timer.Start();vm.AddItemToCommand.Execute(vm.Workspaces.Last());if(exit==0)Check("cards refreshed",vm.InOverview&&vm.Workspaces.Last().Items.Count==1);await Shot(window,Path.Combine(output,"03-overview.png"));}catch(Exception e){File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{File.WriteAllText(Path.Combine(output,"checks.json"),JsonSerializer.Serialize(checks));app.Shutdown();}};window.Show();app.Run();return exit;}}
